def _bond_spanning_tree(bonds, n_atoms):
    """Order bonds as a parent->child spanning forest for whole-molecule unwrapping.

    The low-level ``make_whole`` routine relocates each bonded atom to the
    nearest periodic image of its partner, so the bond list must describe a
    spanning forest in which every parent atom is visited before its children.
    Ordering bonds by atom index does not guarantee this for branched or wrapped
    molecules, which can leave a molecule split across the periodic boundary.
    This performs a breadth-first traversal of every bonded component and
    returns the tree edges oriented parent->child in traversal order.
    """
    from collections import deque

    adjacency = [[] for _ in range(n_atoms)]
    for pair in bonds:
        atom_a, atom_b = int(pair[0]), int(pair[1])
        adjacency[atom_a].append(atom_b)
        adjacency[atom_b].append(atom_a)

    visited = [False] * n_atoms
    tree = []
    for root in range(n_atoms):
        if visited[root] or not adjacency[root]:
            continue
        visited[root] = True
        queue = deque((root,))
        while queue:
            parent = queue.popleft()
            for child in adjacency[parent]:
                if not visited[child]:
                    visited[child] = True
                    tree.append((parent, child))
                    queue.append(child)

    if not tree:
        return np.empty((0, 2), dtype=np.int32)
    return np.asarray(tree, dtype=np.int32)


